// AUTO-GENERATED pipeline step (Phase 0 pattern): parse Una's scouted opportunities
// from ~/una/opportunities.md into typed OpenCallEntry objects.
//
// Design rules:
//  - LOCAL SOURCE ONLY: reads Kate's local markdown; the generated TS is what ships.
//    Raw local DBs never reach the client.
//  - INCLUDE: status === 'active', a verifiable http(s) URL, a parseable deadline
//    (date or 'rolling'), and a kind in scope (grant/fellowship/prize/accelerator/
//    sandbox/hackathon/research-lab). Conferences/roles/courses/challenges are OUT
//    of scope for Open Calls (they belong to Events / other surfaces).
//  - The CH/UAE-home relocation stop-rule is Kate's PERSONAL application filter, NOT a
//    public-display rule — so it is NOT applied here. Public Open Calls shows all active
//    opportunities.
//
// Regenerate: node scripts/ingest/unaOpenCalls.cjs
const fs = require('fs');
const path = require('path');
const os = require('os');

const SRC = path.join(os.homedir(), 'una', 'opportunities.md');
const OUT = path.resolve(__dirname, '..', '..', 'src', 'data', 'openCallEntries.una.ts');

const text = fs.readFileSync(SRC, 'utf8');
const lines = text.split('\n');

const headerIdx = lines.findIndex((l) => l.includes('| id | title | kind |'));
if (headerIdx < 0) {
  console.error('ERROR: ranked-radar table header not found in', SRC);
  process.exit(1);
}
const COLS = 15;

function extractUrl(s) {
  const m = s.match(/https?:\/\/[^\s)\]]+/);
  return m ? m[0].replace(/[)\]]+$/, '') : null;
}
function parseDate(s) {
  const m = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[0];
  const m2 = s.match(/(\d{4})-(\d{2})/);
  if (m2) return m2[0] + '-01';
  return null;
}
const KIND_MAP = {
  grant: 'grant',
  fellowship: 'fellowship',
  prize: 'prize',
  accelerator: 'accelerator',
  sandbox: 'sandbox',
  hackathon: 'hackathon',
  'research-lab': 'research-lab',
};
function mapKind(k) {
  const k0 = String(k).split('/')[0].trim();
  return KIND_MAP[k0] || null;
}
function mapRegion(mobility) {
  if (/UAE|HOME/i.test(mobility)) return 'UAE';
  if (/CH_RELOCATE/i.test(mobility)) return 'EU';
  return 'Global';
}
function esc(s) {
  return String(s)
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .replace(/`/g, '\\`')
    .replace(/\n+/g, ' ')
    .trim();
}

const items = [];
for (let i = headerIdx + 1; i < lines.length; i++) {
  const line = lines[i];
  if (line.startsWith('##')) break; // end of the ranked-radar table
  if (!line.startsWith('|')) continue;
  const cells = line.split('|').slice(1, -1).map((c) => c.trim());
  if (cells.length !== COLS) continue;
  const [id, title, kind, , , , , , mobility, , deadline, , , status, note] = cells;
  if (!/^(grant|fel|role|conf|ws|org|course|ch|comm):/.test(id)) continue;
  if (status !== 'active') continue;
  if (/---/.test(title)) continue;
  const category = mapKind(kind);
  if (!category) continue;
  const url = extractUrl(`${note} ${title}`);
  if (!url) continue;
  let countdown;
  if (/rolling/i.test(deadline)) {
    countdown = "{ kind: 'rolling' }";
  } else {
    const d = parseDate(deadline);
    if (!d) continue; // no verifiable deadline -> skip (can't show countdown)
    // asStated = the issuer's own wording (required by openCallEntries.integrity test)
    countdown = `{ kind: 'deadline', date: new Date('${d}'), asStated: '${esc(deadline)}' }`;
  }
  let host;
  try {
    host = new URL(url).hostname.replace(/^www\./, '');
  } catch {
    continue;
  }
  items.push(
    `  {\n` +
      `    id: 'una_${esc(id)}',\n` +
      `    title: '${esc(title)}',\n` +
      `    organizer: '${esc(host)}',\n` +
      `    url: '${esc(url)}',\n` +
      `    region: '${mapRegion(mobility)}',\n` +
      `    category: '${category}',\n` +
      `    countdown: ${countdown},\n` +
      `    notes: '${esc(note).slice(0, 280)}',\n` +
      `    verifiedAt: '${new Date().toISOString().slice(0, 10)}',\n` +
      `    provenance: 'una',\n` +
      `  }`
  );
}

const out =
  `// AUTO-GENERATED by scripts/ingest/unaOpenCalls.cjs — do not edit by hand.\n` +
  `// Source: ~/una/opportunities.md (Una's scouted opportunities, ranked radar).\n` +
  `// Regenerate: node scripts/ingest/unaOpenCalls.cjs\n` +
  `import type { OpenCallEntry } from './openCallEntries';\n\n` +
  `export const unaScoutedOpenCalls: OpenCallEntry[] = [\n${items.join(',\n')}\n];\n`;

fs.writeFileSync(OUT, out);
console.log(`WROTE ${items.length} Una-scouted open calls -> ${OUT}`);
